// CSD_RATIONALE_BEGIN
// Root cause: 49.7% accuracy plateau is caused by semantic mismatches — the model
// generates grammatically valid SQL with wrong tables, columns, or missing predicates
// (146/300 syntax-valid-but-wrong examples). The underlying model (Qwen3.5-4B) needs
// more context to reason about which tables/columns/joins/filters to use.
//
// Key hypothesis: Extending the unconstrained preamble from 5 to 50 tokens gives the
// model chain-of-thought reasoning space to analyze the question and schema BEFORE
// constrained SQL generation. The preamble tokens become part of constrainedPrompt
// (via `prompt + generated[..|generated| - |currentConstrainedOut|]`), providing rich
// context that grounds the parser-controlled SQL generation to the correct schema elements.
//
// Evidence for feasibility: avg 14 tokens used per example against 900-step budget;
// slowest example is 29s against 600s limit. A 50-token preamble adds <5s/example.
//
// Additional fix: Replace `next == "<<"` with `RenderedEndsWith(generated, "<<")` for
// correct multi-token delimiter detection per API contract.
//
// Guidance: Instruct the model to analyze schema and think step-by-step, encouraging
// productive chain-of-thought in the preamble that seeds correct SQL decisions.
//
// Generation: Keep GroupBoostedConstrainedStep(6.0) from best attempt (49.7%).
// No minSQLTokens guard (attempt 42 showed this hurts accuracy by blocking short correct SQL).
// Fallback: CloseSpanWithinBudget for any open span at end.
// CSD_RATIONALE_END
// CSD_PROOF_SKETCH_BEGIN
// Invariant 1: parser_validity
//   insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
//
// Phase 1 (preamble, while !insideConstrainedOut):
//   When RenderedEndsWith(generated, "<<") fires, we set currentConstrainedOut := [].
//   IsValidPrefix([]) holds by method precondition. On EOS break, insideConstrainedOut
//   stays false, making the implication vacuously true.
//
// Phase 2 (OpenConstrainedSpan):
//   Only runs when !insideConstrainedOut. Postcondition sets currentConstrainedOut := [];
//   IsValidPrefix([]) holds by precondition.
//
// Phase 3 (constrained loop):
//   IsCompletePrefix close branch: CloseConstrainedSpan sets insideConstrainedOut := false,
//   making implication vacuous; currentConstrainedOut := [].
//   Normal step branch: GroupBoostedConstrainedStep hard-masks to parser-valid tokens plus
//   EOS; AppendConstrainedToken extends currentConstrainedOut by one parser-valid token,
//   preserving IsValidPrefix by the parser monotone-extension contract.
//   EOS+close path: same as close branch above.
//
// Phase 4 (CloseSpanWithinBudget):
//   Postcondition guarantees insideOut ==> parser.IsValidPrefix(currentOut). Both
//   closed-span and still-open cases satisfy the invariant.
//
// Invariant 2: progress
//   |generated| <= |generatedPrefix| + steps
//
// Phase 1: Each UnconstrainedStep increments steps by 1 and appends at most 1 token
//   (0 on EOS break, 1 on non-EOS). Invariant preserved each iteration.
//
// Phase 2: OpenConstrainedSpan increments steps by 1 and appends exactly 1 "<<" token.
//   Both sides grow by 1. Invariant preserved.
//
// Phase 3: Close branch: steps += 1, CloseConstrainedSpan appends at most 1 ">>" token.
//   Normal branch: GroupBoostedConstrainedStep costs 1 step (EOS consumed counts);
//   AppendConstrainedToken appends 1 token with 0 additional step. Net: 1 step, 1 token.
//   EOS+close: steps += 1 (EOS) + 1 (close), generated += at most 1 (">>"). Net: 2 steps,
//   at most 1 token. All paths preserve |generated| <= |generatedPrefix| + steps.
//
// Phase 4: CloseSpanWithinBudget postcondition: |generatedOut| <= |generated| + closeBudget
//   where closeBudget = maxSteps - steps. We set steps := maxSteps, so
//   |generated_final| <= |generatedPrefix| + steps_old + (maxSteps - steps_old)
//                      = |generatedPrefix| + maxSteps = |generatedPrefix| + steps_final.
//   Invariant preserved.
// CSD_PROOF_SKETCH_END

generated := generatedPrefix;
insideConstrainedOut := insideConstrained;
currentConstrainedOut := currentConstrained;
cost := 0;

var guidance: string := "Analyze the database schema and the question carefully. Identify the correct tables, columns, join conditions, and filter predicates. Think through the SQL structure step by step. Then write a complete SQL query as: SQL: <<SELECT ... FROM ... [JOIN ...] [WHERE ...] [GROUP BY ...] [HAVING ...] [ORDER BY ...]>>. Use ONLY the exact table and column names from the schema provided.";
helpers.AppendTaskGuidance(lm, guidance);

var steps: nat := 0;
var preambleBudget: nat := 50;
var preambleSteps: nat := 0;

// Phase 1: Extended unconstrained preamble for chain-of-thought reasoning.
// Allows the model to analyze the schema/question before constrained SQL generation.
while steps < maxSteps && preambleSteps < preambleBudget && !insideConstrainedOut
  invariant 0 <= steps <= maxSteps
  invariant 0 <= preambleSteps <= preambleBudget
  invariant lm.ValidTokensIdsLogits()
  invariant !insideConstrainedOut ==> currentConstrainedOut == []
  invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant |generated| <= |generatedPrefix| + steps
  decreases maxSteps - steps
{
  var next := helpers.UnconstrainedStep(lm, prompt, generated);
  steps := steps + 1;
  preambleSteps := preambleSteps + 1;
  if next == eosToken {
    break;
  } else {
    generated := generated + [next];
    if RenderedEndsWith(generated, "<<") {
      insideConstrainedOut := true;
      currentConstrainedOut := [];
    }
  }
}

// Phase 2: Force "<<" if the model hasn't naturally opened a constrained span.
if !insideConstrainedOut && steps < maxSteps {
  var og, oi, oc := helpers.OpenConstrainedSpan(lm, generated);
  generated := og;
  insideConstrainedOut := oi;
  currentConstrainedOut := oc;
  steps := steps + 1;
}

// Phase 3: Constrained SQL generation with group-boosted hard masking.
// Close immediately on IsCompletePrefix; handle EOS gracefully.
while steps < maxSteps && insideConstrainedOut
  invariant 0 <= steps <= maxSteps
  invariant lm.ValidTokensIdsLogits()
  invariant !insideConstrainedOut ==> currentConstrainedOut == []
  invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant |generated| <= |generatedPrefix| + steps
  decreases maxSteps - steps
{
  if parser.IsCompletePrefix(currentConstrainedOut) {
    var cg, ci, cc := helpers.CloseConstrainedSpan(lm, parser, generated, currentConstrainedOut);
    generated := cg;
    insideConstrainedOut := ci;
    currentConstrainedOut := cc;
    steps := steps + 1;
    break;
  } else {
    var constrainedPrompt := prompt + generated[..|generated| - |currentConstrainedOut|];
    var next := helpers.GroupBoostedConstrainedStep(
      lm, parser, constrainedPrompt, currentConstrainedOut, validTokenGroups, 6.0, eosToken
    );
    steps := steps + 1;
    if next == eosToken {
      if parser.IsCompletePrefix(currentConstrainedOut) && steps < maxSteps {
        var cg, ci, cc := helpers.CloseConstrainedSpan(lm, parser, generated, currentConstrainedOut);
        generated := cg;
        insideConstrainedOut := ci;
        currentConstrainedOut := cc;
        steps := steps + 1;
      }
      break;
    } else {
      var ag, ai, ac := helpers.AppendConstrainedToken(
        lm, parser, generated, currentConstrainedOut, next
      );
      generated := ag;
      insideConstrainedOut := ai;
      currentConstrainedOut := ac;
    }
  }
}

// Phase 4: If span still open and budget remains, attempt clean closure.
if insideConstrainedOut && steps < maxSteps {
  var closeBudget := maxSteps - steps;
  var cg, ci, cc := helpers.CloseSpanWithinBudget(
    lm, parser, prompt, generated, currentConstrainedOut, eosToken, closeBudget
  );
  generated := cg;
  insideConstrainedOut := ci;
  currentConstrainedOut := cc;
  steps := maxSteps;
}

cost := steps;

